                ".emptyState{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;height:100%;padding:40px;max-width:720px;margin:0 auto;text-align:center}.emptyState b{color:var(--text);font-size:16px;font-weight:700}.emptyState span{color:var(--muted);font-size:13px;line-height:1.6}";
